import{_ as r,o as t,c as a,a2 as o}from"./chunks/framework.BG8d4IEm.js";const u=JSON.parse('{"title":"书签订阅 RSS","description":"","frontmatter":{"tags":["工具"]},"headers":[],"relativePath":"posts/2020-03-24-rss-bookmark.md","filePath":"posts/2020-03-24-rss-bookmark.md"}'),s={name:"posts/2020-03-24-rss-bookmark.md"};function i(l,e,n,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="书签订阅-rss" tabindex="-1">书签订阅 RSS <a class="header-anchor" href="#书签订阅-rss" aria-label="Permalink to &quot;书签订阅 RSS&quot;">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>笔者使用 <a href="https://www.inoreader.com/" target="_blank" rel="noreferrer">inoreader</a> 订阅 RSS。 但是知乎专栏,微博等无法转换为 RSS。google 后发现利用 <a href="https://docs.rsshub.app/" target="_blank" rel="noreferrer">RSSHub</a> 可将各种资源转换为 RSS 订阅。由于手动转换网址为 RSS 过于麻烦,研究后发现了如下解决方案。</p><h2 id="预备知识-url-scheme" tabindex="-1">预备知识 URL scheme <a class="header-anchor" href="#预备知识-url-scheme" aria-label="Permalink to &quot;预备知识 URL scheme&quot;">​</a></h2><p>参考 <a href="https://tools.ietf.org/html/rfc1738#section-5" target="_blank" rel="noreferrer">URL rfc</a> 资源定位符的一般形式为 <code>scheme:schemepart</code>。其中 <code>scheme</code> 决定了资源的访问策略。 在浏览器中一般使用 <code>http,https</code> 访问资源,实际访问地址还可为其他形式</p><ul><li><code>mailto</code> 打开邮箱 <a href="mailto:zenheart_register@163.com" target="_blank" rel="noreferrer">mailto:zenheart_register@163.com</a></li><li><code>tel</code> 拨打电话 <a href="tel:1234" target="_blank" rel="noreferrer">tel:1234</a></li><li><code>file:</code> 打开本地文件</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>你甚至可以使用 <a href="vscode:" target="_blank" rel="noreferrer"><strong>vscode:</strong></a> 打开 VSCode 编辑器,只要相关应用设置了符合 <code>scheme</code> 策略,浏览器便会根据 <code>scheme</code> 打开应用</p></div><p>可查看 <a href="https://developer.mozilla.org/zh-CN/docs/Web/HTML/Element/a#%E5%88%9B%E5%BB%BA%E4%B8%80%E4%B8%AAemail%E9%93%BE%E6%8E%A5" target="_blank" rel="noreferrer">mdn</a> 进一步理解各种 scheme 的使用。</p><p>基于上述原则实际上访问地址也可为一段 js 代码。采用 <code>javascript:</code> 即可。例如 <a href="javascript:alert(&#39;hello world&#39;)">javascript:alert(&#39;hello world&#39;)</a> 该链接会触发 <code>alert(&#39;hello world&#39;)</code> 执行。</p><p>基于此 scheme 我们可以将当前地址转换为 RSS 订阅的逻辑保存为 <code>javascript:</code> 的标签即可。</p><h2 id="url-转换为-rss-订阅" tabindex="-1">URL 转换为 RSS 订阅 <a class="header-anchor" href="#url-转换为-rss-订阅" aria-label="Permalink to &quot;URL 转换为 RSS 订阅&quot;">​</a></h2><p>假设将 github issue 转换为 RSS 订阅。参考 <a href="https://docs.rsshub.app/programming.html#github" target="_blank" rel="noreferrer">RSSHub github issue</a> 可知需将 issues 链接转换为 <code>https://rsshub.app/github/issue/用户名/用户仓库</code> 订阅地址。</p><p>在访问 issue 时,我们需要把从当前地址提取 <code>/用户名/用户仓库</code> 转换为 <code>https://rsshub.app/github/issue/用户名/用户仓库</code> RSS 订阅地址</p><p>利用 <a href="https://developer.mozilla.org/zh-CN/docs/Web/API/Location" target="_blank" rel="noreferrer">location</a> 对象可以很方便的从 URL 提取相应信息。</p><p>转换为 RSS 的地址如何触发 <a href="https://www.inoreader.com/" target="_blank" rel="noreferrer">inoreader</a> 订阅。利用 <code>https://www.inoreader.com/bookmarklet/subscribe/RSS地址</code> 触发订阅。</p><p>综合上述逻辑访问 <a href="https://gist.github.com/zenHeart/8aec3f90366829afba32858bb38e8daa" target="_blank" rel="noreferrer">RSS gist</a> 查看结果,拖动此标签到书签栏查看效果 <a style="display:inline-block;padding:1px 6px;color:#fff;background:#32a0eb;border-radius:4px;" href="javascript:(function()%7B(function()%20%7Blet%20rssData%20%3D%20%7Bzhihu%3A%20%7Bvalidator%3A%20%2Fzhuanlan.zhihu.com%2F%2CurlToRss%3A%20location%20%3D%3E%60https%3A%2F%2Frss.lilydjwg.me%2Fzhihuzhuanlan%2F%24%7Blocation.pathname.split(&#39;%2F&#39;)%5B1%5D%7D%60%7D%2CgithubIssue%3A%20%7Bvalidator%3A%20%2Fgithub%5C.com%5C.*issues%2F%2CurlToRss%3A%20location%20%3D%3E%60https%3A%2F%2Frsshub.app%2Fgithub%2Fissue%2F%24%7Blocation.pathname.split(&#39;%2F&#39;).slice(1%2C%203).join(&#39;%2F&#39;)%7D%60%7D%7D%3Blet%20validatorRss%20%3D%20(url%2C%20validator)%20%3D%3E%20validator.test(url)%3Blet%20addRss%20%3D%20url%20%3D%3E%20%60https%3A%2F%2Fwww.inoreader.com%2F%3Fadd_feed%3D%24%7Burl%7D%60%3Blet%20subscribe%20%3D%20(a%2C%20w%2C%20h)%20%3D%3E%20%7Bvar%20b%20%3D%20window.screenLeft%20!%3D%20undefined%20%3F%20window.screenLeft%20%3A%20screen.left%3Bvar%20c%20%3D%20window.screenTop%20!%3D%20undefined%20%3F%20window.screenTop%20%3A%20screen.top%3Bwidth%20%3D%20window.innerWidth%3F%20window.innerWidth%3A%20document.documentElement.clientWidth%3F%20document.documentElement.clientWidth%3A%20screen.width%3Bheight%20%3D%20window.innerHeight%3F%20window.innerHeight%3A%20document.documentElement.clientHeight%3F%20document.documentElement.clientHeight%3A%20screen.height%3Bvar%20d%20%3D%20width%20%2F%202%20-%20w%20%2F%202%20%2B%20b%3Bvar%20e%20%3D%20height%20%2F%202%20-%20h%20%2F%202%20%2B%20c%3Bvar%20f%20%3D%20window.open(a%2Cnew%20Date().getTime()%2C&#39;width%3D&#39;%20%2Bw%20%2B&#39;%2C%20height%3D&#39;%20%2Bh%20%2B&#39;%2C%20top%3D&#39;%20%2Be%20%2B&#39;%2C%20left%3D&#39;%20%2Bd%20%2B&#39;location%3Dyes%2Cresizable%3Dyes%2Cstatus%3Dno%2Cscrollbars%3Dno%2Cpersonalbar%3Dno%2Ctoolbar%3Dno%2Cmenubar%3Dno&#39;)%3Bif%20(window.focus)%20%7Bf.focus()%3B%7D%7D%3Blet%20l%20%3D%20location%3Blet%20res%3Bfor%20(let%20k%20in%20rssData)%20%7Blet%20rss%20%3D%20rssData%5Bk%5D%3Bif%20(validatorRss(l.href%2C%20rss.validator))%20%7Bres%20%3Drss.urlToRss(l)%3B%7D%7Dif%20(res)%20%7Bsubscribe(&#39;https%3A%2F%2Fwww.inoreader.com%2Fbookmarklet%2Fsubscribe%2F&#39;%20%2BencodeURIComponent(res)%2C640%2C400)%3B%7D%20else%20%7Bsubscribe(&#39;https%3A%2F%2Fwww.inoreader.com%2Fbookmarklet%2Fsubscribe%2F&#39;%20%2BencodeURIComponent(location.href)%2C640%2C400)%3B%7D%7D)()%7D)()">rss</a></p><h2 id="代码片段保存为标签" tabindex="-1">代码片段保存为标签 <a class="header-anchor" href="#代码片段保存为标签" aria-label="Permalink to &quot;代码片段保存为标签&quot;">​</a></h2><p>既然标签可以执行 javascript 代码,可以建立一个 <code>code</code> 书签,保存常用的脚本标签。此外结合 <a href="https://chrome.google.com/webstore/detail/vimium/dbepggeogbaibhgnhhndojpepiihcmeb" target="_blank" rel="noreferrer">Vimium</a> 实现快捷调用。</p><p>相比 <a href="https://developer.chrome.com/docs/devtools/javascript/snippets?hl=zh-cn" target="_blank" rel="noreferrer">Snippets</a> 需要打开控制台后触发,该方法更方便。</p>',19)])])}const m=r(s,[["render",i]]);export{u as __pageData,m as default};
